#include <iostream>
#include <fstream>
#include <vector>
#include <climits>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    long long maxSum = LLONG_MIN;
    int maxStart = 0, maxEnd = 0;
    long long curSum = 0;
    int curStart = 0;

    for (int i = 0; i < n; i++) {
        curSum += T[i];
        if (curSum > maxSum) {
            maxSum = curSum;
            maxStart = curStart;
            maxEnd = i;
        }
        if (curSum < 0) {
            curSum = 0;
            curStart = i + 1;
        }
    }

    int dl = maxEnd - maxStart + 1;
    cout << "a) Maksymalna suma podciagu: " << maxSum << endl;
    cout << endl << "b) Pozycja poczatkowa: " << maxStart + 1
         << ", koncowa: " << maxEnd + 1
         << ", dlugosc: " << dl << endl;
    cout << endl << "c) Elementy:";
    for (int i = maxStart; i <= maxEnd; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm Kadane'a w wersji O(n). Kluczowa obserwacja: jesli biezaca suma spadnie ponizej 0, nie oplaca sie kontynuowac biezacego podciagu — lepiej zaczac od nowa. Sledzenie pozycji wymaga dodatkowej zmiennej curStart.

